html:
{#
    WARIIRI TRAVEL & LOGISTICS SERVICE
    Professional Ticket Sales Invoice - Frappe/ERPNext Jinja Print Format

    DocType: Sales Invoice

    Passenger info now comes from the Items table rows:
      Title, Name, Reference, Description
    If your Reference fieldname is different, edit the "ref_value" line in the items loop.
#}

{% set brand_blue = "#0788B5" %}
{% set brand_navy = "#0B4A68" %}
{% set brand_orange = "#F7941D" %}
{% set brand_soft = "#F4F9FC" %}
{% set border_color = "#D6E4EC" %}
{% set text_color = "#17324A" %}
{% set muted_color = "#647887" %}

{# ------------------------- Customer mapping ------------------------- #}
{% set customer_name = doc.customer_name or doc.customer or "" %}
{% set customer_mobile = doc.get("contact_mobile") or doc.get("mobile_no") or frappe.db.get_value("Customer", doc.customer, "mobile_no") or "" %}

{# -------------------------- Ticket mapping -------------------------- #}
{% set sale_type = doc.get("type") or doc.get("custom_type") or doc.get("sales_type") or "Ticket" %}
{% set flight = doc.get("flight") or doc.get("custom_flight") or doc.get("airline") or "" %}
{% set ticket_no = doc.get("ticket_no") or doc.get("custom_ticket_no") or doc.get("ticket_number") or "" %}
{% set route_from = doc.get("from") or doc.get("from_location") or doc.get("custom_from") or doc.get("origin") or "" %}
{% set route_to = doc.get("to") or doc.get("to_location") or doc.get("custom_to") or doc.get("destination") or "" %}
{% set departure_datetime = doc.get("departure_datetime") or doc.get("custom_departure_datetime") or doc.get("departure_date_time") or "" %}

{# -------------------------- Invoice state --------------------------- #}
{% if doc.docstatus == 2 %}
    {% set status_label = "CANCELLED" %}
    {% set status_class = "is-cancelled" %}
{% elif doc.docstatus == 0 %}
    {% set status_label = "DRAFT" %}
    {% set status_class = "is-draft" %}
{% elif (doc.outstanding_amount or 0) <= 0 %}
    {% set status_label = "PAID" %}
    {% set status_class = "is-paid" %}
{% else %}
    {% set status_label = "PAYMENT DUE" %}
    {% set status_class = "is-due" %}
{% endif %}

{# ------- Which optional item columns have at least one value? ------- #}
{% set ns = namespace(show_name=false, show_ref=false) %}
{% for item in doc.items %}
    {% if item.get("custom_title") or item.get("custom_name") %}{% set ns.show_name = true %}{% endif %}
    {% if item.get("custom_refference") %}{% set ns.show_ref = true %}{% endif %}
{% endfor %}

<style>
    @page {
        size: A4;
        margin: 10mm;
    }

    * {
        box-sizing: border-box;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    body,
    .print-format {
        margin: 0;
        font-family: Arial, Helvetica, sans-serif;
        color: {{ text_color }};
        font-size: 11px;
        line-height: 1.4;
        background: #ffffff;
    }

    .ticket-invoice {
        position: relative;
        width: 100%;
        max-width: 760px;
        margin: 0 auto;
        padding: 8px 10px 0;
        background: #ffffff;
    }

    .watermark {
        position: fixed;
        top: 43%;
        left: 14%;
        right: 14%;
        z-index: 0;
        transform: rotate(-24deg);
        color: rgba(11, 74, 104, 0.08);
        font-size: 78px;
        font-weight: 900;
        letter-spacing: 10px;
        text-align: center;
        pointer-events: none;
    }

    .invoice-content {
        position: relative;
        z-index: 1;
    }

    .brand-header {
        width: 100%;
        margin-bottom: 6px;
        text-align: center;
    }

    .brand-header img {
        max-width: 100%;
        height: auto;
    }

    .brand-bar {
        display: table;
        width: 100%;
        height: 6px;
        margin: 1px 0 15px;
        border-collapse: collapse;
    }

    .brand-bar-blue,
    .brand-bar-orange {
        display: table-cell;
        height: 6px;
    }

    .brand-bar-blue {
        width: 82%;
        background: {{ brand_blue }};
    }

    .brand-bar-orange {
        width: 18%;
        background: {{ brand_orange }};
    }

    .invoice-heading-table {
        width: 100%;
        margin-bottom: 14px;
        border-collapse: collapse;
    }

    .invoice-heading-table td {
        padding: 0;
        border: 0;
        vertical-align: middle;
    }

    .invoice-heading-main {
        width: 68%;
    }

    .invoice-kicker {
        margin-bottom: 4px;
        color: {{ brand_orange }};
        font-size: 9px;
        font-weight: 800;
        letter-spacing: 1.5px;
        text-transform: uppercase;
    }

    .invoice-title {
        margin: 0;
        color: {{ brand_navy }};
        font-size: 26px;
        font-weight: 900;
        line-height: 1;
        letter-spacing: 2.5px;
        text-transform: uppercase;
    }

    .invoice-reference {
        margin-top: 7px;
        color: {{ muted_color }};
        font-size: 10px;
    }

    .invoice-reference strong {
        color: {{ text_color }};
        font-size: 12px;
    }

    .status-cell {
        width: 32%;
        text-align: right;
    }

    .status-pill {
        display: inline-block;
        min-width: 112px;
        padding: 7px 12px;
        border-radius: 999px;
        color: #ffffff !important;
        font-size: 10px;
        font-weight: 900;
        text-align: center;
        letter-spacing: 0.8px;
    }

    .status-pill.is-paid { background: #16855B; }
    .status-pill.is-due { background: {{ brand_orange }}; }
    .status-pill.is-draft { background: #7B8794; }
    .status-pill.is-cancelled { background: #C2413B; }

    .info-grid {
        display: table;
        width: 100%;
        margin-bottom: 12px;
        border: 1px solid {{ border_color }};
        border-radius: 10px;
        background: {{ brand_soft }};
        overflow: hidden;
        page-break-inside: avoid;
    }

    .info-column {
        display: table-cell;
        width: 50%;
        padding: 12px 14px;
        vertical-align: top;
    }

    .info-column + .info-column {
        border-left: 1px solid {{ border_color }};
    }

    .section-label {
        margin-bottom: 8px;
        color: {{ brand_blue }};
        font-size: 9px;
        font-weight: 900;
        letter-spacing: 1px;
        text-transform: uppercase;
    }

    .party-name {
        margin-bottom: 6px;
        color: {{ brand_navy }};
        font-size: 15px;
        font-weight: 900;
        text-transform: uppercase;
    }

    .data-row {
        display: table;
        width: 100%;
        margin-top: 5px;
    }

    .data-label,
    .data-value {
        display: table-cell;
        vertical-align: top;
    }

    .data-label {
        width: 42%;
        color: {{ muted_color }};
        font-size: 9px;
        font-weight: 700;
    }

    .data-value {
        color: {{ text_color }};
        font-size: 10px;
        font-weight: 700;
        text-align: right;
    }

    .journey-card {
        margin-bottom: 12px;
        border: 2px solid {{ brand_blue }};
        border-top: 5px solid {{ brand_orange }};
        border-radius: 11px;
        background: #ffffff;
        page-break-inside: avoid;
        overflow: hidden;
    }

    .journey-top {
        display: table;
        width: 100%;
        padding: 13px 14px 11px;
    }

    .route-location,
    .route-arrow {
        display: table-cell;
        vertical-align: middle;
    }

    .route-location {
        width: 42%;
    }

    .route-location.to-location {
        text-align: right;
    }

    .route-caption {
        color: {{ muted_color }};
        font-size: 8px;
        font-weight: 800;
        letter-spacing: 1px;
        text-transform: uppercase;
    }

    .route-name {
        margin-top: 2px;
        color: {{ brand_navy }};
        font-size: 20px;
        font-weight: 900;
        text-transform: uppercase;
    }

    .route-arrow {
        width: 16%;
        color: {{ brand_orange }};
        font-size: 25px;
        font-weight: 900;
        text-align: center;
    }

    /* Cells share the width equally, so hidden cells leave no gap */
    .journey-details {
        display: table;
        table-layout: fixed;
        width: 100%;
        border-top: 1px solid {{ border_color }};
        background: {{ brand_soft }};
    }

    .journey-detail {
        display: table-cell;
        padding: 9px 11px;
        border-right: 1px solid {{ border_color }};
        vertical-align: top;
    }

    .journey-detail:last-child {
        border-right: 0;
    }

    .journey-detail-label {
        color: {{ brand_blue }};
        font-size: 8px;
        font-weight: 900;
        letter-spacing: 0.55px;
        text-transform: uppercase;
    }

    .journey-detail-value {
        margin-top: 3px;
        color: {{ text_color }};
        font-size: 10px;
        font-weight: 800;
        word-break: break-word;
    }

    .panel-title {
        margin: 13px 0 6px;
        color: {{ brand_navy }};
        font-size: 11px;
        font-weight: 900;
        letter-spacing: 0.65px;
        text-transform: uppercase;
    }

    .items-table {
        width: 100%;
        border-collapse: collapse;
        table-layout: auto;
        page-break-inside: auto;
    }

    .items-table thead {
        display: table-header-group;
    }

    .items-table th {
        padding: 8px 7px;
        border: 1px solid #ffffff;
        color: #ffffff !important;
        background: {{ brand_navy }} !important;
        font-size: 8.5px;
        font-weight: 900;
        letter-spacing: 0.45px;
        text-transform: uppercase;
    }

    .items-table td {
        padding: 8px 7px;
        border: 1px solid {{ border_color }};
        color: {{ text_color }};
        font-size: 9.5px;
        vertical-align: middle;
    }

    .items-table tbody tr {
        page-break-inside: avoid;
    }

    .items-table tbody tr:nth-child(even) {
        background: {{ brand_soft }};
    }

    /* Service: only as wide as its content */
    .items-table .col-service {
        width: 1%;
        white-space: nowrap;
    }

    /* Name: takes the remaining space */
    .items-table .col-name {
        width: auto;
    }

    .item-desc {
        white-space: normal;
        max-width: 200px;
        margin-top: 2px;
        color: #444;
        font-size: 8.5px;
        font-weight: normal;
        line-height: 1.25;
    }

    .text-center {
        text-align: center;
    }

    .text-right {
        text-align: right;
    }

    .item-code {
        color: {{ brand_navy }};
        font-weight: 900;
    }

    .person-name {
        font-weight: 900;
        text-transform: uppercase;
    }

    .qty-value,
    .amount-value {
        font-weight: 900;
    }

    .summary-wrap {
        width: 100%;
        margin-top: 10px;
        text-align: right;
        page-break-inside: avoid;
    }

    .summary-box {
        display: inline-block;
        width: 48%;
        min-width: 310px;
        border: 1px solid {{ border_color }};
        border-radius: 8px;
        overflow: hidden;
        text-align: left;
    }

    .summary-table {
        width: 100%;
        border-collapse: collapse;
    }

    .summary-table td {
        padding: 7px 10px;
        border-bottom: 1px solid {{ border_color }};
        font-size: 9.5px;
    }

    .summary-table tr:last-child td {
        border-bottom: 0;
    }

    .summary-label {
        color: {{ muted_color }};
        font-weight: 700;
    }

    .summary-value {
        color: {{ text_color }};
        font-weight: 900;
        text-align: right;
        white-space: nowrap;
    }

    .grand-total-row td {
        padding: 10px;
        color: #ffffff !important;
        background: {{ brand_navy }} !important;
        font-size: 12px;
        font-weight: 900;
    }

    .balance-row td {
        color: #ffffff !important;
        background: {{ brand_orange }} !important;
        font-weight: 900;
    }

    .amount-words {
        margin-top: 7px;
        padding: 8px 10px;
        border-left: 4px solid {{ brand_orange }};
        background: {{ brand_soft }};
        color: {{ text_color }};
        font-size: 9px;
        page-break-inside: avoid;
    }

    .amount-words strong {
        color: {{ brand_navy }};
    }

    .invoice-note {
        margin-top: 12px;
        padding: 8px 10px;
        border: 1px dashed {{ border_color }};
        color: {{ muted_color }};
        font-size: 8.5px;
        page-break-inside: avoid;
    }

    .print-meta {
        display: table;
        width: 100%;
        margin-top: 14px;
        color: {{ muted_color }};
        font-size: 8.5px;
        page-break-inside: avoid;
    }

    .print-meta-left,
    .print-meta-right {
        display: table-cell;
        width: 50%;
    }

    .print-meta-right {
        text-align: right;
    }

    .print-meta strong {
        color: {{ text_color }};
    }

    .invoice-footer {
        margin-top: 18px;
        padding-top: 9px;
        border-top: 1px solid {{ border_color }};
        color: {{ brand_navy }};
        font-size: 8.5px;
        font-weight: 700;
        text-align: center;
        line-height: 1.55;
        page-break-inside: avoid;
    }

    .footer-accent {
        display: table;
        width: 100%;
        height: 5px;
        margin-top: 8px;
    }

    .footer-accent-blue,
    .footer-accent-orange {
        display: table-cell;
        height: 5px;
    }

    .footer-accent-blue {
        width: 82%;
        background: {{ brand_blue }};
    }

    .footer-accent-orange {
        width: 18%;
        background: {{ brand_orange }};
    }

    @media print {
        .ticket-invoice {
            max-width: none;
            padding: 0;
        }

        .status-pill,
        .items-table th,
        .grand-total-row td,
        .balance-row td,
        .brand-bar-blue,
        .brand-bar-orange,
        .footer-accent-blue,
        .footer-accent-orange {
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
        }
    }
</style>

<div class="ticket-invoice">

    {% if doc.docstatus == 0 %}
        <div class="watermark">DRAFT</div>
    {% elif doc.docstatus == 2 %}
        <div class="watermark">CANCELLED</div>
    {% endif %}

    <div class="invoice-content">

        <!-- Letterhead -->
        <div class="brand-header">
            {{ letter_head }}
        </div>

        <div class="brand-bar">
            <span class="brand-bar-blue"></span>
            <span class="brand-bar-orange"></span>
        </div>

        <!-- Invoice heading -->
        <!--<table class="invoice-heading-table">-->
        <!--    <tr>-->
        <!--        <td class="invoice-heading-main">-->
        <!--            <div class="invoice-kicker">Travel Ticket Billing</div>-->
        <!--            <h1 class="invoice-title">Sales Invoice</h1>-->
        <!--            <div class="invoice-reference">-->
        <!--                Invoice No. <strong>{{ doc.name or "" }}</strong>-->
        <!--            </div>-->
        <!--        </td>-->

        <!--        <td class="status-cell">-->
        <!--            <span class="status-pill {{ status_class }}">-->
        <!--                {{ status_label }}-->
        <!--            </span>-->
        <!--        </td>-->
        <!--    </tr>-->
        <!--</table>-->

        <!-- Customer and invoice dates -->
        <div class="info-grid">
            <div class="info-column">
                <div class="section-label">Billed To</div>
                <div class="party-name">{{ customer_name }}</div>

                {% if customer_mobile %}
                <div class="data-row">
                    <span class="data-label">Mobile Number</span>
                    <span class="data-value">{{ customer_mobile }}</span>
                </div>
                {% endif %}
            </div>

            <div class="info-column">
                <div class="section-label">Invoice Details</div>

                <div class="data-row">
                    <span class="data-label">Invoice No.</span>
                    <span class="data-value">{{ doc.name or "" }}</span>
                </div>

                <div class="data-row">
                    <span class="data-label">Posting Date</span>
                    <span class="data-value">
                        {% if doc.posting_date %}
                            {{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}
                        {% else %}
                            -
                        {% endif %}
                    </span>
                </div>

                {% if doc.due_date %}
                <div class="data-row">
                    <span class="data-label">Payment Due Date</span>
                    <span class="data-value">{{ frappe.utils.formatdate(doc.due_date, "dd-MM-yyyy") }}</span>
                </div>
                {% endif %}

                <div class="data-row">
                    <span class="data-label">Invoice Type</span>
                    <span class="data-value">{{ sale_type or "Ticket" }}</span>
                </div>
            </div>
        </div>

        <!-- Journey details -->
        {% if flight or ticket_no or route_from or route_to or departure_datetime %}
        <div class="journey-card">
            <div class="journey-top">
                <div class="route-location">
                    <div class="route-caption">From</div>
                    <div class="route-name">{{ route_from or "-" }}</div>
                </div>

                <div class="route-arrow">&#8594;</div>

                <div class="route-location to-location">
                    <div class="route-caption">To</div>
                    <div class="route-name">{{ route_to or "-" }}</div>
                </div>
            </div>

            <div class="journey-details">
                {% if flight %}
                <div class="journey-detail">
                    <div class="journey-detail-label">Airline / Flight</div>
                    <div class="journey-detail-value">{{ flight }}</div>
                </div>
                {% endif %}

                {% if ticket_no %}
                <div class="journey-detail">
                    <div class="journey-detail-label">Ticket No.</div>
                    <div class="journey-detail-value">{{ ticket_no }}</div>
                </div>
                {% elif doc.custom_vissa_no %}
                <div class="journey-detail">
                    <div class="journey-detail-label">Visa No.</div>
                    <div class="journey-detail-value">{{ doc.custom_vissa_no }}</div>
                </div>
                {% endif %}

                {% if departure_datetime %}
                <div class="journey-detail">
                    <div class="journey-detail-label">Departure</div>
                    <div class="journey-detail-value">
                        {{ frappe.utils.format_datetime(departure_datetime, "dd-MM-yyyy HH:mm") }}
                    </div>
                </div>
                {% endif %}

                <div class="journey-detail">
                    <div class="journey-detail-label">Payment Terms</div>
                    <div class="journey-detail-value">
                        {{ doc.payment_terms_template or "Immediate" }}
                    </div>
                </div>
            </div>
        </div>
        {% endif %}

        <!-- Items (passenger info lives in the item rows) -->
        <div class="panel-title">Invoice Items</div>
        <table class="items-table">
            <thead>
                <tr>
                    <th style="width: 30px;">SN.</th>
                    <th class="col-service" style="text-align: left;">Service</th>
                    {% if ns.show_name %}
                    <th class="col-name" style="text-align: left;">Name</th>
                    {% endif %}
                    {% if ns.show_ref %}
                    <th style="width: 80px;">Reference</th>
                    {% endif %}
                    <th style="width: 40px;">Qty</th>
                    <th style="width: 70px; text-align: right;">Price</th>
                    <th style="width: 80px; text-align: right;">Amount</th>
                </tr>
            </thead>
            <tbody>
                {% for item in doc.items %}
                {% set desc = (item.description or "")|striptags|trim %}
                <tr>
                    <td class="text-center">{{ loop.index }}</td>

                    <td class="col-service">
                        <span class="item-code">{{ item.item_code or "" }}</span>
                        {% if desc and desc|lower != (item.item_code or "")|trim|lower %}
                        <div class="item-desc">{{ desc }}</div>
                        {% endif %}
                    </td>

                    {% if ns.show_name %}
                    <td class="col-name">
                        <span class="person-name">
                            {{ item.get("custom_title") or "" }} {{ item.get("custom_name") or "" }}  {{" - "}} {{item.get("custom_mobile") or "" }} 
                        </span>
                    </td>
                    {% endif %}

                    {% if ns.show_ref %}
                    <td class="text-center">
                        <b>{{ item.get("custom_refference") or "" }}</b>
                    </td>
                    {% endif %}

                    <td class="text-center">
                        <span class="qty-value">{{ item.qty or 0 }}</span>
                    </td>
                    <td class="text-right">
                        {{ frappe.utils.fmt_money(item.rate or 0, currency=doc.currency) }}
                    </td>
                    <td class="text-right">
                        <span class="amount-value">
                            {{ frappe.utils.fmt_money(item.amount or 0, currency=doc.currency) }}
                        </span>
                    </td>
                </tr>
                {% endfor %}
            </tbody>
        </table>

        <!-- Totals -->
        <div class="summary-wrap">
            <div class="summary-box">
                <table class="summary-table">
                    <tr>
                        <td class="summary-label">Subtotal</td>
                        <td class="summary-value">
                            {{ frappe.utils.fmt_money(doc.total or 0, currency=doc.currency) }}
                        </td>
                    </tr>

                    {% if (doc.discount_amount or 0) != 0 %}
                    <tr>
                        <td class="summary-label">Discount</td>
                        <td class="summary-value">
                            {{ frappe.utils.fmt_money(doc.discount_amount or 0, currency=doc.currency) }}
                        </td>
                    </tr>
                    {% endif %}

                    {% if (doc.total_taxes_and_charges or 0) != 0 %}
                    <tr>
                        <td class="summary-label">Tax</td>
                        <td class="summary-value">
                            {{ frappe.utils.fmt_money(doc.total_taxes_and_charges or 0, currency=doc.currency) }}
                        </td>
                    </tr>
                    {% endif %}

                    <tr class="grand-total-row">
                        <td>Grand Total</td>
                        <td class="text-right">
                            {{ frappe.utils.fmt_money(doc.grand_total or 0, currency=doc.currency) }}
                        </td>
                    </tr>

                    {% if (doc.paid_amount or 0) != 0 %}
                    <tr>
                        <td class="summary-label">Paid Amount</td>
                        <td class="summary-value">
                            {{ frappe.utils.fmt_money(doc.paid_amount or 0, currency=doc.currency) }}
                        </td>
                    </tr>
                    {% endif %}

                    {% if (doc.outstanding_amount or 0) > 0 %}
                    <tr class="balance-row">
                        <td>Balance Due</td>
                        <td class="text-right">
                            {{ frappe.utils.fmt_money(doc.outstanding_amount or 0, currency=doc.currency) }}
                        </td>
                    </tr>
                    {% endif %}
                </table>
            </div>
        </div>

        {% if doc.in_words %}
        <div class="amount-words">
            <strong>Amount in Words:</strong>
            {{ doc.in_words }}
        </div>
        {% endif %}

        {% if doc.remarks %}
        <div class="invoice-note">
            <strong>Remarks:</strong> {{ doc.remarks }}
        </div>
        {% endif %}

        <div class="print-meta">
            <div class="print-meta-left">
                Created by:
                <strong>{{ frappe.db.get_value("User", doc.owner, "full_name") or doc.owner or "" }}</strong>
            </div>
            <div class="print-meta-right">
                Printed on:
                <strong>{{ frappe.utils.format_datetime(frappe.utils.now(), "dd-MM-yyyy HH:mm") }}</strong>
            </div>
        </div>

